-- Question bank for topic 1 (JVM, JDK and JRE): 10 questions in each kind and difficulty group, 40 in total.

INSERT INTO mcq_questions (id, topic_id, kind, difficulty, prompt, code_snippet, option_1, option_2, option_3, option_4, correct_option, explanation) VALUES ('ac9d05c8-b942-547e-9629-60724f7605b9', '480e01d7-ca63-5c82-8c09-a7b61243756e', 'THEORY', 'EASY', 'Which part of the Java platform contains the compiler, javac?', NULL, 'JVM', 'JRE', 'JDK', 'JIT', 2, 'The JDK adds the compiler and developer tools on top of the JRE. A JRE alone can run programs but cannot compile them.');
INSERT INTO mcq_questions (id, topic_id, kind, difficulty, prompt, code_snippet, option_1, option_2, option_3, option_4, correct_option, explanation) VALUES ('2009602d-97db-5028-9408-a8390b0ef2a2', '480e01d7-ca63-5c82-8c09-a7b61243756e', 'THEORY', 'EASY', 'What does javac produce from a .java source file?', NULL, 'Machine code for the current operating system', 'Bytecode stored in a .class file', 'A ready-to-run .jar archive', 'A copy of the source with comments removed', 1, 'javac translates source into platform-neutral bytecode, written to .class files.');
INSERT INTO mcq_questions (id, topic_id, kind, difficulty, prompt, code_snippet, option_1, option_2, option_3, option_4, correct_option, explanation) VALUES ('809ee3f6-d54e-50db-a57b-88868625e15c', '480e01d7-ca63-5c82-8c09-a7b61243756e', 'THEORY', 'EASY', 'What does the JRE consist of?', NULL, 'The JVM plus the core class libraries', 'The compiler plus a debugger', 'Only the JVM', 'An IDE and a build tool', 0, 'JRE = JVM + core libraries. It is what you need to run a Java program.');
INSERT INTO mcq_questions (id, topic_id, kind, difficulty, prompt, code_snippet, option_1, option_2, option_3, option_4, correct_option, explanation) VALUES ('830db990-bedb-585f-9d95-b53bab631e05', '480e01d7-ca63-5c82-8c09-a7b61243756e', 'THEORY', 'EASY', 'Why can the same .class file run on Windows and on Linux?', NULL, 'Each operating system has its own JVM that understands bytecode', 'Bytecode is machine code that every CPU accepts', 'javac recompiles the file each time it starts', 'Java programs do not use the operating system', 0, 'Bytecode targets the JVM, not the hardware. Each platform supplies a JVM that executes it.');
INSERT INTO mcq_questions (id, topic_id, kind, difficulty, prompt, code_snippet, option_1, option_2, option_3, option_4, correct_option, explanation) VALUES ('364117f0-6019-5914-bb2f-1d3750e86831', '480e01d7-ca63-5c82-8c09-a7b61243756e', 'THEORY', 'EASY', 'Where are objects created with new stored?', NULL, 'On the JVM stack', 'On the heap', 'In the program counter register', 'In the compiler', 1, 'Objects live on the heap. The stack holds method frames with local variables and references.');
INSERT INTO mcq_questions (id, topic_id, kind, difficulty, prompt, code_snippet, option_1, option_2, option_3, option_4, correct_option, explanation) VALUES ('12d28c22-8bcf-5fa2-a2f3-02a3efb31d19', '480e01d7-ca63-5c82-8c09-a7b61243756e', 'THEORY', 'HARD', 'What does the JIT compiler do?', NULL, 'Turns frequently executed bytecode into native machine code at run time', 'Compiles .java files when you build the project', 'Removes the need for garbage collection', 'Checks bytecode for safety before loading', 0, 'The JIT watches for hot methods and compiles them to native code, which is why Java gets faster after warm-up.');
INSERT INTO mcq_questions (id, topic_id, kind, difficulty, prompt, code_snippet, option_1, option_2, option_3, option_4, correct_option, explanation) VALUES ('890de780-7dfe-5f17-9ac4-d8fc51c40ae5', '480e01d7-ca63-5c82-8c09-a7b61243756e', 'THEORY', 'HARD', 'Which class loader loads core classes such as java.lang.Object?', NULL, 'The application class loader', 'The bootstrap class loader', 'A custom class loader you write', 'The JIT class loader', 1, 'The bootstrap loader is the root of the hierarchy and loads the core runtime classes.');
INSERT INTO mcq_questions (id, topic_id, kind, difficulty, prompt, code_snippet, option_1, option_2, option_3, option_4, correct_option, explanation) VALUES ('1d731364-aa00-58e5-8c7c-0a6c6fac378f', '480e01d7-ca63-5c82-8c09-a7b61243756e', 'THEORY', 'HARD', 'What is the job of the bytecode verifier?', NULL, 'Optimise loops for speed', 'Check that loaded bytecode follows the JVM safety rules before it runs', 'Free unused objects', 'Translate bytecode to source code', 1, 'Verification stops malformed or tampered bytecode from corrupting memory or breaking type safety.');
INSERT INTO mcq_questions (id, topic_id, kind, difficulty, prompt, code_snippet, option_1, option_2, option_3, option_4, correct_option, explanation) VALUES ('57c941b3-ab90-5692-b5f3-59b843869fff', '480e01d7-ca63-5c82-8c09-a7b61243756e', 'THEORY', 'HARD', 'Which memory area is private to each thread and holds one frame per method call?', NULL, 'The heap', 'The method area', 'The JVM stack', 'The string pool', 2, 'Every thread has its own JVM stack of frames. The heap and method area are shared.');
INSERT INTO mcq_questions (id, topic_id, kind, difficulty, prompt, code_snippet, option_1, option_2, option_3, option_4, correct_option, explanation) VALUES ('80e0e106-41b3-56e9-ac6f-90ae573983d2', '480e01d7-ca63-5c82-8c09-a7b61243756e', 'THEORY', 'HARD', 'When does an object become eligible for garbage collection?', NULL, 'As soon as any variable pointing to it is set to null', 'When no live reference path from a GC root reaches it', 'When the method that created it returns, always', 'When you call finalize() on it', 1, 'Reachability from GC roots decides it. Other references may still keep the object alive.');
INSERT INTO mcq_questions (id, topic_id, kind, difficulty, prompt, code_snippet, option_1, option_2, option_3, option_4, correct_option, explanation) VALUES ('6076b573-b2e1-5fea-9957-a57e5671bf01', '480e01d7-ca63-5c82-8c09-a7b61243756e', 'CODE', 'EASY', 'What does this program print?', 'String s = "Hi";
int x = 5;
System.out.println(s + x);', 'Hi5', 'Hi 5', '5Hi', 'Compile error', 0, '+ with a String concatenates, and the int is converted to text, giving Hi5.');
INSERT INTO mcq_questions (id, topic_id, kind, difficulty, prompt, code_snippet, option_1, option_2, option_3, option_4, correct_option, explanation) VALUES ('865ec10a-2407-5bbd-b767-047e2853586f', '480e01d7-ca63-5c82-8c09-a7b61243756e', 'CODE', 'EASY', 'Which keyword lets the JVM call main without creating an object first?', 'public ____ void main(String[] args) {
  System.out.println("start");
}', 'final', 'static', 'abstract', 'private', 1, 'A static method belongs to the class, so the JVM can call it before any object exists.');
INSERT INTO mcq_questions (id, topic_id, kind, difficulty, prompt, code_snippet, option_1, option_2, option_3, option_4, correct_option, explanation) VALUES ('ba50660a-b61f-5742-abf2-c9c1ce841360', '480e01d7-ca63-5c82-8c09-a7b61243756e', 'CODE', 'EASY', 'Which command compiles a file named Hello.java that declares public class Hello?', '// Hello.java
public class Hello { }', 'javac Hello.java', 'java Hello.class', 'jvm Hello.java', 'compile Hello', 0, 'javac is the compiler. java runs the compiled class.');
INSERT INTO mcq_questions (id, topic_id, kind, difficulty, prompt, code_snippet, option_1, option_2, option_3, option_4, correct_option, explanation) VALUES ('4cb4e5d3-ed95-579f-a3f2-97622cff5437', '480e01d7-ca63-5c82-8c09-a7b61243756e', 'CODE', 'EASY', 'After javac runs on this file, which file appears next to it?', '// Hello.java
public class Hello { }', 'Hello.exe', 'Hello.class', 'Hello.jar', 'Hello.bytecode', 1, 'javac writes one .class file for each class it compiles.');
INSERT INTO mcq_questions (id, topic_id, kind, difficulty, prompt, code_snippet, option_1, option_2, option_3, option_4, correct_option, explanation) VALUES ('e5855ceb-f803-51bc-9a2b-3c6ae7eb228e', '480e01d7-ca63-5c82-8c09-a7b61243756e', 'CODE', 'EASY', 'After the third line runs, can the String object still be reached?', 'String a = new String("x");
String b = a;
b = null;', 'Yes, through a', 'No, setting b to null destroys it', 'Only until the next line runs', 'Only if a is also null', 0, 'Both variables pointed to one object. Clearing b leaves a pointing to it.');
INSERT INTO mcq_questions (id, topic_id, kind, difficulty, prompt, code_snippet, option_1, option_2, option_3, option_4, correct_option, explanation) VALUES ('36124521-233c-5076-82db-8a09e59272a7', '480e01d7-ca63-5c82-8c09-a7b61243756e', 'CODE', 'HARD', 'What happens when this program runs?', 'static void down() { down(); }
public static void main(String[] a) {
  down();
}', 'OutOfMemoryError for the heap', 'StackOverflowError', 'It loops forever with no error', 'Compile error', 1, 'Each call adds a frame to the thread stack. With no end to the recursion the stack runs out and the JVM throws StackOverflowError.');
INSERT INTO mcq_questions (id, topic_id, kind, difficulty, prompt, code_snippet, option_1, option_2, option_3, option_4, correct_option, explanation) VALUES ('4a68c5f6-fde6-59d9-af76-ba8ec04ec078', '480e01d7-ca63-5c82-8c09-a7b61243756e', 'CODE', 'HARD', 'What is the most likely outcome of this loop?', 'List<int[]> keep = new ArrayList<>();
while (true) {
  keep.add(new int[1_000_000]);
}', 'StackOverflowError', 'OutOfMemoryError: Java heap space', 'ArithmeticException', 'The garbage collector frees the arrays so it never ends', 1, 'The list keeps every array reachable, so the collector cannot free them and the heap fills up.');
INSERT INTO mcq_questions (id, topic_id, kind, difficulty, prompt, code_snippet, option_1, option_2, option_3, option_4, correct_option, explanation) VALUES ('09af85c2-f858-51c6-a728-54d13d2ce5ea', '480e01d7-ca63-5c82-8c09-a7b61243756e', 'CODE', 'HARD', 'Is the object eligible for garbage collection after o = null?', 'Object o = new Object();
Object p = o;
o = null;
System.gc();', 'No, p still refers to it', 'Yes, o was the only owner', 'Only after System.gc() returns', 'It depends on the JIT', 0, 'p keeps the object reachable. System.gc() is only a request and does not change reachability.');
INSERT INTO mcq_questions (id, topic_id, kind, difficulty, prompt, code_snippet, option_1, option_2, option_3, option_4, correct_option, explanation) VALUES ('2f35ddf8-a2bf-502c-8275-106ea40f3d47', '480e01d7-ca63-5c82-8c09-a7b61243756e', 'CODE', 'HARD', 'Why might this loop speed up after the first several thousand iterations?', 'for (int i = 0; i < 1_000_000; i++) {
  total += compute(i);
}', 'The JIT compiles the hot compute() method to native code', 'The garbage collector reorders the loop', 'The verifier caches the result', 'javac optimises it while the program runs', 0, 'Hot code is detected at run time and compiled to native code by the JIT, so later iterations run faster.');
INSERT INTO mcq_questions (id, topic_id, kind, difficulty, prompt, code_snippet, option_1, option_2, option_3, option_4, correct_option, explanation) VALUES ('df2af0a7-bd7b-5425-b359-8513d4e204b3', '480e01d7-ca63-5c82-8c09-a7b61243756e', 'CODE', 'HARD', 'What is printed, in order?', 'class A {
  static { System.out.println("A loaded"); }
}
public class Main {
  public static void main(String[] x) {
    System.out.println("start");
    new A();
  }
}', 'A loaded, then start', 'start, then A loaded', 'Only start', 'Compile error', 1, 'Classes load lazily. A is loaded and its static block runs the first time new A() executes, after "start".');
INSERT INTO mcq_questions (id, topic_id, kind, difficulty, prompt, code_snippet, option_1, option_2, option_3, option_4, correct_option, explanation) VALUES ('253e6722-77b3-59d6-b6a2-ef082c1a839d', '480e01d7-ca63-5c82-8c09-a7b61243756e', 'THEORY', 'EASY', 'Which tool packages many .class files into one archive?', NULL, 'javac', 'java', 'jar', 'javap', 2, 'jar bundles compiled classes and resources into a single .jar archive. javac compiles, java runs, javap inspects bytecode.');
INSERT INTO mcq_questions (id, topic_id, kind, difficulty, prompt, code_snippet, option_1, option_2, option_3, option_4, correct_option, explanation) VALUES ('3d5161ee-a249-59b7-b1c2-0802779f97b9', '480e01d7-ca63-5c82-8c09-a7b61243756e', 'THEORY', 'EASY', 'What does "write once, run anywhere" depend on?', NULL, 'Compiling the source separately for every operating system', 'Bytecode plus a JVM built for each platform', 'Interpreting the source text directly on every run', 'Avoiding all library classes', 1, 'The same bytecode runs unchanged because every platform supplies its own JVM that understands it.');
INSERT INTO mcq_questions (id, topic_id, kind, difficulty, prompt, code_snippet, option_1, option_2, option_3, option_4, correct_option, explanation) VALUES ('a760561e-d5a0-5615-bb38-906cd1dcd5fe', '480e01d7-ca63-5c82-8c09-a7b61243756e', 'THEORY', 'EASY', 'What is the minimum you need installed to run an already compiled Java program?', NULL, 'The JDK compiler only', 'A Java runtime (JRE) containing the JVM and core libraries', 'An IDE such as IntelliJ', 'A copy of the source code', 1, 'Running needs the JVM and the core class libraries, which is what a JRE provides. Compiling is what needs the JDK.');
INSERT INTO mcq_questions (id, topic_id, kind, difficulty, prompt, code_snippet, option_1, option_2, option_3, option_4, correct_option, explanation) VALUES ('242f0ae7-5234-5c47-9f1a-ec02fa551d97', '480e01d7-ca63-5c82-8c09-a7b61243756e', 'THEORY', 'EASY', 'What does the JVM interpreter do with bytecode?', NULL, 'Executes it instruction by instruction', 'Turns it back into source code', 'Deletes it after the first read', 'Sends it to javac', 0, 'The interpreter reads each bytecode instruction and carries it out. The JIT later compiles the hot parts to native code.');
INSERT INTO mcq_questions (id, topic_id, kind, difficulty, prompt, code_snippet, option_1, option_2, option_3, option_4, correct_option, explanation) VALUES ('b883cbf2-838a-5795-9a94-98c066e410d2', '480e01d7-ca63-5c82-8c09-a7b61243756e', 'THEORY', 'EASY', 'Which tool prints the bytecode instructions of a compiled class?', NULL, 'javadoc', 'javap', 'jar', 'jshell', 1, 'javap disassembles a .class file so you can read its bytecode. javadoc builds documentation and jshell is an interactive shell.');
INSERT INTO mcq_questions (id, topic_id, kind, difficulty, prompt, code_snippet, option_1, option_2, option_3, option_4, correct_option, explanation) VALUES ('60f97bd2-588f-5f0f-b760-d5c128f88473', '480e01d7-ca63-5c82-8c09-a7b61243756e', 'THEORY', 'HARD', 'What is the difference between the heap and the method area?', NULL, 'The heap holds class metadata, the method area holds objects', 'The heap holds objects, the method area holds class metadata and static data', 'Both hold only local variables', 'The heap is per thread and the method area is shared', 1, 'Objects are allocated on the heap. Class structure, method code and static data live in the method area. Both are shared by all threads.');
INSERT INTO mcq_questions (id, topic_id, kind, difficulty, prompt, code_snippet, option_1, option_2, option_3, option_4, correct_option, explanation) VALUES ('ebfa3194-8d2d-51bd-b585-3bc50daa3619', '480e01d7-ca63-5c82-8c09-a7b61243756e', 'THEORY', 'HARD', 'Why can a JIT compiler sometimes produce faster code than an ahead-of-time compiler?', NULL, 'It skips type checking', 'It watches real run-time behaviour, such as which branches are taken, and optimises for it', 'It never needs garbage collection', 'It compiles source code more strictly', 1, 'The JIT profiles the running program and specialises hot code for what it actually does, which a compiler working before the program runs cannot see.');
INSERT INTO mcq_questions (id, topic_id, kind, difficulty, prompt, code_snippet, option_1, option_2, option_3, option_4, correct_option, explanation) VALUES ('b8da5b9e-a505-5507-af85-11c35e41a7ae', '480e01d7-ca63-5c82-8c09-a7b61243756e', 'THEORY', 'HARD', 'What happens during the linking phase of class loading?', NULL, 'The .java file is read and compiled', 'Bytecode is verified, static fields get default values, and symbolic references are resolved', 'main is called', 'Unused objects are collected', 1, 'Linking has three steps: verification, preparation (static fields get default values) and resolution of symbolic references.');
INSERT INTO mcq_questions (id, topic_id, kind, difficulty, prompt, code_snippet, option_1, option_2, option_3, option_4, correct_option, explanation) VALUES ('217bdb53-f498-5fe0-9c3e-d88569a27c47', '480e01d7-ca63-5c82-8c09-a7b61243756e', 'THEORY', 'HARD', 'How does the class loader delegation model work?', NULL, 'A loader always loads the class itself first', 'A loader asks its parent first and loads the class itself only if the parent cannot', 'Every loader loads a different set of classes in parallel', 'Classes are loaded in alphabetical order', 1, 'Parent-first delegation stops application code from replacing core classes such as java.lang.String with its own version.');
INSERT INTO mcq_questions (id, topic_id, kind, difficulty, prompt, code_snippet, option_1, option_2, option_3, option_4, correct_option, explanation) VALUES ('4681c7b7-cf83-583e-8961-0edb0cd66595', '480e01d7-ca63-5c82-8c09-a7b61243756e', 'THEORY', 'HARD', 'Which of these can keep an object reachable for the garbage collector?', NULL, 'A comment that mentions the object', 'A local variable in a method that is still running', 'An unused import statement', 'The name of the source file', 1, 'Local variables on a live thread stack are GC roots, so anything they reference stays alive. Comments and imports are not references.');
INSERT INTO mcq_questions (id, topic_id, kind, difficulty, prompt, code_snippet, option_1, option_2, option_3, option_4, correct_option, explanation) VALUES ('68bab7e5-3abd-52ac-94b6-ab9e318ca980', '480e01d7-ca63-5c82-8c09-a7b61243756e', 'CODE', 'EASY', 'What does this program print?', 'int x = 3;
int y = 4;
System.out.println(x * y);', '7', '12', '34', 'Compile error', 1, 'The * operator multiplies the two ints, giving 12.');
INSERT INTO mcq_questions (id, topic_id, kind, difficulty, prompt, code_snippet, option_1, option_2, option_3, option_4, correct_option, explanation) VALUES ('b4ab3e0c-2c7a-5903-b6ae-f5dd6476b333', '480e01d7-ca63-5c82-8c09-a7b61243756e', 'CODE', 'EASY', 'What does this program print?', 'String a = "Java";
System.out.println(a.length());', '3', '4', '5', 'Compile error', 1, '"Java" has four characters, so length() returns 4.');
INSERT INTO mcq_questions (id, topic_id, kind, difficulty, prompt, code_snippet, option_1, option_2, option_3, option_4, correct_option, explanation) VALUES ('10bc27d3-6628-5a65-93cc-2879afcca0b2', '480e01d7-ca63-5c82-8c09-a7b61243756e', 'CODE', 'EASY', 'App.java has been compiled to App.class. Which command runs it?', '// App.java
public class App {
  public static void main(String[] args) {
    System.out.println("ok");
  }
}', 'java App', 'java App.class', 'javac App', 'run App.java', 0, 'The java launcher takes the class name without the extension. javac is the compiler.');
INSERT INTO mcq_questions (id, topic_id, kind, difficulty, prompt, code_snippet, option_1, option_2, option_3, option_4, correct_option, explanation) VALUES ('3b786d41-db63-5605-85da-bac5624cbbae', '480e01d7-ca63-5c82-8c09-a7b61243756e', 'CODE', 'EASY', 'What does this program print?', 'System.out.println(10 / 4);', '2.5', '2', '3', 'Compile error', 1, 'Both operands are ints, so the division is integer division and the fraction is dropped.');
INSERT INTO mcq_questions (id, topic_id, kind, difficulty, prompt, code_snippet, option_1, option_2, option_3, option_4, correct_option, explanation) VALUES ('914e0e6e-3f89-5587-ae93-884581c45e29', '480e01d7-ca63-5c82-8c09-a7b61243756e', 'CODE', 'EASY', 'Where does the variable count live while run() executes?', 'void run() {
  int count = 5;
}', 'On the heap', 'In the stack frame of the run() call', 'In the method area', 'In the string pool', 1, 'Local primitives live in the frame that the call to run() pushes on the thread stack.');
INSERT INTO mcq_questions (id, topic_id, kind, difficulty, prompt, code_snippet, option_1, option_2, option_3, option_4, correct_option, explanation) VALUES ('bd9dddad-277d-5b9d-a6b9-4486f208b043', '480e01d7-ca63-5c82-8c09-a7b61243756e', 'CODE', 'HARD', 'What does this program print?', 'String s1 = new String("hi");
String s2 = new String("hi");
System.out.println(s1 == s2);', 'true', 'false', 'Compile error', 'It depends on the JIT', 1, 'new always creates a separate object, and == compares references, so the result is false. Use equals() to compare content.');
INSERT INTO mcq_questions (id, topic_id, kind, difficulty, prompt, code_snippet, option_1, option_2, option_3, option_4, correct_option, explanation) VALUES ('e1420e29-ebeb-51a5-a9ba-d08de98b4d9f', '480e01d7-ca63-5c82-8c09-a7b61243756e', 'CODE', 'HARD', 'What does this program print?', 'String a = "hi";
String b = "hi";
System.out.println(a == b);', 'true', 'false', 'Compile error', 'It throws an exception', 0, 'Both literals point to the same pooled String object, so the references are equal.');
INSERT INTO mcq_questions (id, topic_id, kind, difficulty, prompt, code_snippet, option_1, option_2, option_3, option_4, correct_option, explanation) VALUES ('331bf84f-4083-5281-aac3-4e3bcb9b4dc9', '480e01d7-ca63-5c82-8c09-a7b61243756e', 'CODE', 'HARD', 'What is the output?', 'class Demo {
  static { System.out.println("static"); }
  { System.out.println("instance"); }
  Demo() { System.out.println("ctor"); }
  public static void main(String[] a) {
    new Demo();
    new Demo();
  }
}', 'static, instance, ctor, instance, ctor', 'static, static, instance, instance, ctor, ctor', 'instance, ctor, static, instance, ctor', 'static, ctor, instance, ctor, instance', 0, 'The static block runs once when the class loads. For each new object the instance block runs before the constructor body.');
INSERT INTO mcq_questions (id, topic_id, kind, difficulty, prompt, code_snippet, option_1, option_2, option_3, option_4, correct_option, explanation) VALUES ('3139adec-ce65-527c-a4fa-928dac2cd09d', '480e01d7-ca63-5c82-8c09-a7b61243756e', 'CODE', 'HARD', 'What happens when this runs?', 'int[] a = new int[3];
System.out.println(a[3]);', 'It prints 0', 'It fails to compile', 'It throws ArrayIndexOutOfBoundsException', 'It prints null', 2, 'Valid indexes are 0 to 2. The compiler cannot see the mistake, so the JVM throws the exception at run time.');
INSERT INTO mcq_questions (id, topic_id, kind, difficulty, prompt, code_snippet, option_1, option_2, option_3, option_4, correct_option, explanation) VALUES ('0988fb96-d27f-5254-8d4a-850ea40b521b', '480e01d7-ca63-5c82-8c09-a7b61243756e', 'CODE', 'HARD', 'After which line does the object first become eligible for garbage collection?', 'Object a = new Object(); // 1
Object b = a;            // 2
a = null;                // 3
b = null;                // 4', 'After line 2', 'After line 3', 'After line 4', 'Never, it needs System.gc()', 2, 'Two references pointed to the object. Only after b = null is the last reference gone, and System.gc() is not required.');
